//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::int::write_decimal`; the
//! native twin is `benches/native/Bench/IntWriteDecimal.lean`.
//! Int.repr is Lean code: a negative value costs native two strings and an append, where a
//! translator replaces it with one formatting call (on the stack, then one new string object)

#![allow(unused_parens, unused_imports, unused_variables, unused_mut)]
#![allow(
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]
#![allow(clippy::identity_op, clippy::let_and_return)]

use lean_runtime::semantics::int;
use lean_runtime_bench::*;
use std::hint::black_box;

#[inline(never)]
fn kernel(inp: &(), n: u64) -> u64 {
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = mix(acc, {
            let mut b = StackBuf::new();
            let _ = int::write_decimal(&int_arg(int_box(((x >> 34) as i64) - (1 << 29))), &mut b);
            make_ascii_string(b.as_bytes()).byte_size()
        });
    }
    acc
}

fn main() {
    run(|| (), kernel)
}
